var e={tuning:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Geführte Kalibrierungsassistenten. Wähle unten einen aus.`}},pick:{label:{t:0,b:{t:2,i:[{t:3}],s:`Assistent`}}},params:{start:{t:0,b:{t:2,i:[{t:3}],s:`Start-PA`}},factor:{t:0,b:{t:2,i:[{t:3}],s:`Faktor (PA/mm)`}},height:{t:0,b:{t:2,i:[{t:3}],s:`Höhe (mm)`}}},pa:{title:{t:0,b:{t:2,i:[{t:3}],s:`Pressure Advance`}},step1:{t:0,b:{t:2,i:[{t:3}],s:`1. Tuning-Turm planen`}},plan:{t:0,b:{t:2,i:[{t:3}],s:`Turm planen`}},command:{t:0,b:{t:2,i:[{t:3}],s:`Diesen Befehl ausführen`}},commandHint:{t:0,b:{t:2,i:[{t:3}],s:`Sende ihn direkt vor dem Druck (oder füge ihn in den Start-G-code deines Testmodells ein); PA steigt mit dem Turm an, während er gedruckt wird.`}},table:{height:{t:0,b:{t:2,i:[{t:3}],s:`Höhe (mm)`}},pa:{t:0,b:{t:2,i:[{t:3}],s:`PA`}}},step2:{t:0,b:{t:2,i:[{t:3}],s:`2. Die am besten aussehende Höhe eingeben`}},bestHeight:{t:0,b:{t:2,i:[{t:3}],s:`Beste Z-Höhe (mm)`}},computed:{t:0,b:{t:2,i:[{t:3,v:`Berechneter Pressure Advance: `},{t:4,k:`pa`}]}},applyButton:{t:0,b:{t:2,i:[{t:3}],s:`PA anwenden`}},apply:{applied:{t:0,b:{t:2,i:[{t:3,v:`Pressure Advance `},{t:4,k:`value`},{t:3,v:` angewendet`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`Drucker ist beschäftigt - kann jetzt nicht angewendet werden`}},out_of_range:{t:0,b:{t:2,i:[{t:3,v:`Wert außerhalb des Bereichs (max. `},{t:4,k:`max`},{t:3,v:`)`}]}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:`Anwenden fehlgeschlagen: `},{t:4,k:`error`}]}}}},retraction:{title:{t:0,b:{t:2,i:[{t:3}],s:`Rückzug`}},params:{start:{t:0,b:{t:2,i:[{t:3}],s:`Startlänge (mm)`}},factor:{t:0,b:{t:2,i:[{t:3}],s:`Faktor (mm/mm)`}},height:{t:0,b:{t:2,i:[{t:3}],s:`Höhe (mm)`}}},step1:{t:0,b:{t:2,i:[{t:3}],s:`1. Tuning-Turm planen`}},plan:{t:0,b:{t:2,i:[{t:3}],s:`Turm planen`}},command:{t:0,b:{t:2,i:[{t:3}],s:`Diesen Befehl ausführen`}},commandHint:{t:0,b:{t:2,i:[{t:3}],s:`Sende ihn direkt vor dem Druck (oder füge ihn in den Start-G-code deines Testmodells ein); die Rückzugslänge steigt mit dem Turm an, während er gedruckt wird. Erfordert ein konfiguriertes [firmware_retraction].`}},table:{height:{t:0,b:{t:2,i:[{t:3}],s:`Höhe (mm)`}},value:{t:0,b:{t:2,i:[{t:3}],s:`Länge (mm)`}}},step2:{t:0,b:{t:2,i:[{t:3}],s:`2. Die am besten aussehende Höhe eingeben`}},bestHeight:{t:0,b:{t:2,i:[{t:3}],s:`Beste Z-Höhe (mm)`}},computed:{t:0,b:{t:2,i:[{t:3,v:`Berechnete Rückzugslänge: `},{t:4,k:`value`},{t:3,v:` mm`}]}},applyButton:{t:0,b:{t:2,i:[{t:3}],s:`Rückzug anwenden`}},apply:{applied:{t:0,b:{t:2,i:[{t:3,v:`Rückzugslänge `},{t:4,k:`value`},{t:3,v:` mm angewendet`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`Drucker ist beschäftigt - kann jetzt nicht angewendet werden`}},out_of_range:{t:0,b:{t:2,i:[{t:3,v:`Wert außerhalb des Bereichs (max. `},{t:4,k:`max`},{t:3,v:`)`}]}},no_firmware_retraction:{t:0,b:{t:2,i:[{t:3}],s:`Auf diesem Drucker ist kein [firmware_retraction]-Abschnitt konfiguriert`}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:`Anwenden fehlgeschlagen: `},{t:4,k:`error`}]}}}},temp:{title:{t:0,b:{t:2,i:[{t:3}],s:`Temperatur`}},params:{start:{t:0,b:{t:2,i:[{t:3}],s:`Starttemperatur (°C)`}},factor:{t:0,b:{t:2,i:[{t:3}],s:`Faktor (°C/mm)`}},band:{t:0,b:{t:2,i:[{t:3}],s:`Bandhöhe (mm)`}},height:{t:0,b:{t:2,i:[{t:3}],s:`Höhe (mm)`}},heater:{t:0,b:{t:2,i:[{t:3}],s:`Heizelement`}}},heaters:{extruder:{t:0,b:{t:2,i:[{t:3}],s:`Extruder`}},extruder1:{t:0,b:{t:2,i:[{t:3}],s:`Extruder 1`}},extruder2:{t:0,b:{t:2,i:[{t:3}],s:`Extruder 2`}},heater_bed:{t:0,b:{t:2,i:[{t:3}],s:`Druckbett`}}},step1:{t:0,b:{t:2,i:[{t:3}],s:`1. Temperaturturm planen`}},plan:{t:0,b:{t:2,i:[{t:3}],s:`Turm planen`}},command:{t:0,b:{t:2,i:[{t:3}],s:`Diesen Befehl ausführen`}},commandHint:{t:0,b:{t:2,i:[{t:3}],s:`Sende ihn direkt vor dem Druck (oder füge ihn in den Start-G-code deines Testmodells ein); die Zieltemperatur wechselt einmal pro Band, während der Turm wächst, sodass die Düse Zeit hat, sich einzupendeln.`}},table:{range:{t:0,b:{t:2,i:[{t:3}],s:`Z-Bereich (mm)`}},temp:{t:0,b:{t:2,i:[{t:3}],s:`Temp. (°C)`}}},step2:{t:0,b:{t:2,i:[{t:3}],s:`2. Die am besten aussehende Höhe eingeben`}},bestHeight:{t:0,b:{t:2,i:[{t:3}],s:`Beste Z-Höhe (mm)`}},computed:{t:0,b:{t:2,i:[{t:3,v:`Beste Temperatur: `},{t:4,k:`temp`},{t:3,v:` °C`}]}},noBand:{t:0,b:{t:2,i:[{t:3}],s:`Gib eine Höhe innerhalb des Turms ein`}},applyButton:{t:0,b:{t:2,i:[{t:3}],s:`Temperatur setzen`}},apply:{applied:{t:0,b:{t:2,i:[{t:4,k:`heater`},{t:3,v:` auf `},{t:4,k:`value`},{t:3,v:` °C gesetzt`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`Drucker ist beschäftigt - kann jetzt nicht angewendet werden`}},unknown_heater:{t:0,b:{t:2,i:[{t:3}],s:`Unbekanntes Heizelement`}},out_of_range:{t:0,b:{t:2,i:[{t:3,v:`Wert außerhalb des Bereichs (max. `},{t:4,k:`max`},{t:3,v:`)`}]}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:`Anwenden fehlgeschlagen: `},{t:4,k:`error`}]}}}},flow:{title:{t:0,b:{t:2,i:[{t:3}],s:`Durchfluss`}},step1:{t:0,b:{t:2,i:[{t:3}],s:`1. Eine bekannte Länge extrudieren, dann messen, was tatsächlich herausgekommen ist`}},requested:{t:0,b:{t:2,i:[{t:3}],s:`Angeforderte Länge (mm)`}},measured:{t:0,b:{t:2,i:[{t:3}],s:`Gemessene Länge (mm)`}},current:{t:0,b:{t:2,i:[{t:3}],s:`Aktuelle rotation_distance`}},fetch:{t:0,b:{t:2,i:[{t:3}],s:`Vom Drucker auslesen`}},calc:{t:0,b:{t:2,i:[{t:3}],s:`Berechnen`}},step2:{t:0,b:{t:2,i:[{t:3}],s:`2. Korrektur`}},result:{t:0,b:{t:2,i:[{t:3,v:`Neue rotation_distance: `},{t:4,k:`value`}]}},flowPercent:{t:0,b:{t:2,i:[{t:3,v:`Entsprechender Slicer-Durchfluss: `},{t:4,k:`percent`},{t:3,v:`%`}]}},snippetTitle:{t:0,b:{t:2,i:[{t:3}],s:`In deinen [extruder]-Abschnitt einfügen, dann SAVE_CONFIG ausführen und neu starten`}},notLive:{t:0,b:{t:2,i:[{t:3}],s:`Der Durchfluss kann nicht live gesetzt werden - wende ihn mit einem Speichern der Konfiguration und einem Neustart an, nicht sofort.`}},noCurrent:{t:0,b:{t:2,i:[{t:3}],s:`Konnte nicht vom Drucker ausgelesen werden - gib deine [extruder] rotation_distance manuell ein.`}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Anleitung`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Anleitung zu den Tuning-Assistenten`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Schließen`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Was ist Pressure Advance?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`PA (Druckvorhalt) gleicht die Druckverzögerung in der Düse aus, schärft Ecken und reduziert Nachsickern und Aufwölbungen. Jedes Filament hat seinen eigenen besten Wert.`}}},workflow:{title:{t:0,b:{t:2,i:[{t:3}],s:`So funktionieren die Assistenten`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Plane einen Tuning-Turm, drucke ihn (der Wert steigt mit zunehmender Höhe an), lies die sauberste Höhe ab und wende dann den passenden Wert an. Speichere ihn in der printer.cfg, um ihn dauerhaft zu behalten.`}}},retraction:{title:{t:0,b:{t:2,i:[{t:3}],s:`Was ist Rückzug?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Der Rückzug zieht das Filament bei Verfahrbewegungen zurück, um Nachsickern und Fädenziehen zu verhindern. Zu wenig hinterlässt Fäden; zu viel kann Verstopfungen oder Lücken verursachen. Dieser Assistent stimmt die Firmware-Rückzugslänge ab.`}}},temperature:{title:{t:0,b:{t:2,i:[{t:3}],s:`Was ist ein Temperaturturm?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Ein Temperaturturm druckt dieselbe Form bei gestuften Düsentemperaturen, sodass du diejenige mit der besten Schichthaftung, Oberflächenqualität und dem geringsten Fädenziehen für dein Filament auswählen kannst.`}}},flow:{title:{t:0,b:{t:2,i:[{t:3}],s:`Was ist eine Durchflusskalibrierung?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Die Durchflusskalibrierung korrigiert, wie viel Filament der Extruder tatsächlich fördert. Fordere eine bekannte Länge an, miss, was herausgekommen ist, und der Assistent passt die rotation_distance an. Klipper hat keine Live-Durchflusseinstellung, daher kommt der neue Wert in die printer.cfg.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glossar`}}}},glossary:{pressureAdvance:{term:{t:0,b:{t:2,i:[{t:3}],s:`Pressure Advance`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Eine Klipper-Einstellung, die die Extrusion vor Geschwindigkeitsänderungen anpasst, um schärfere Ecken zu erzielen.`}}},tuningTower:{term:{t:0,b:{t:2,i:[{t:3}],s:`Tuning-Turm`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Ein hoher Druck, bei dem TUNING_TOWER einen Parameter stetig mit der Höhe ändert, damit du die beste Schicht auswählen kannst.`}}},firmwareRetraction:{term:{t:0,b:{t:2,i:[{t:3}],s:`Firmware-Rückzug`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Klippers Funktion [firmware_retraction]: G10/G11 für Rückzug und Rücknahme werden vom Drucker gesteuert und lassen sich live mit SET_RETRACTION abstimmen.`}}},temperatureTower:{term:{t:0,b:{t:2,i:[{t:3}],s:`Temperaturturm`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Ein Testdruck, der in Bänder unterteilt ist und bei jeweils unterschiedlicher Düsentemperatur gehalten wird, um die beste Drucktemperatur eines Filaments zu finden.`}}},rotationDistance:{term:{t:0,b:{t:2,i:[{t:3}],s:`rotation_distance`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Wie viele mm Filament der Extruder pro Motorumdrehung fördert. Eine Verringerung fördert mehr Filament; die Durchflusskalibrierung stimmt diesen Wert ab.`}}}}}}};export{e as default};